{
  "technical_and_design_decisions": [
    "U1: NIO support is implemented by wiring a Grizzly-based NIO HTTP transport alongside the existing blocking transport; a boolean property in deploy.properties selects the stack at startup, with the classic blocking transport remaining the default for backward compatibility.",
    "U1: WebSocket support is delivered as a new Mule module/transport exposing inbound and outbound WebSocket endpoints as flow components, including an XML schema (XSD), namespace handler, and message receiver/dispatcher implementations built on the NIO stack.",
    "U2: Registry pairing is implemented as a Mule agent that reads the registry key from configuration, performs the pairing handshake with the registry REST API, persists pairing state locally, and hooks application lifecycle events (deploy/undeploy) so HTTP endpoints of all deployed apps are registered and manageable in the paired registry.",
    "U3: The dynamic lookup component is implemented as a message processor (dynamic router) that resolves target endpoints at runtime via expressions and/or registry-based dynamic endpoint resolution, with a lookup result cache and configurable timeout/fallback behavior.",
    "U4: Throttling policies are enforced by policy handlers injected at flow endpoint level and integrated with registry-supplied policy definitions; a token-bucket rate-limiting algorithm is used, with requests exceeding the limit rejected with a configurable error response.",
    "U5: Custom business events and transaction IDs are logged through Mule's event-tracking mechanism plus SLF4J/Log4J MDC entries for transaction IDs, enabled when running in development/debug logging mode.",
    "U6: MVEL is upgraded to version 2.1.8 in all module POMs; the existing MVEL and DataMapper test suites are executed and any API regressions fixed.",
    "U7: JDBC connectivity for Oracle, PostgreSQL, Sybase, MS SQL Server and DB2 is delivered as preconfigured data-source definitions/templates plus connector dialect settings so connections work with minimal user configuration; integration tests run against real vendor database instances.",
    "U8: SQL query logging is implemented at DEBUG level inside the JDBC transport via a logging connection/statement wrapper, controlled by a configuration option so users can see all executed queries.",
    "All development activities include unit testing and self code review; system/integration testing, documentation and release packaging are separate WBS activities."
  ],
  "assumptions": [
    "A single developer performs all work; all figures are effort in work-hours, not elapsed calendar time.",
    "The referenced internal wiki specifications are not accessible; scope is inferred from the user story text and knowledge of Mule ESB 3.x architecture.",
    "The existing Mule 3.x codebase, Maven build and CI infrastructure are in place and reused; no build-system rework is needed.",
    "Test environments are available: a running registry instance for U2/U4 and database instances for Oracle, PostgreSQL, Sybase, MS SQL Server and DB2 for U7/U8; environment provisioning effort is excluded.",
    "Vendor JDBC drivers that cannot be redistributed (Oracle, Sybase, DB2, MS SQL Server) are supplied by the end user; only configuration support is implemented for them.",
    "MySQL support is already complete per U7 and is excluded from the estimate.",
    "No changes are required on the registry server side; only ESB-side integration work is included.",
    "U5 applies to development-mode logging only; no UI or persistent event store is built.",
    "Documentation covers user/configuration documentation and release notes only.",
    "Standard 8-hour working day assumed for effort sizing."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment planning, requirements analysis and high-level design",
      "activity_description": "Analyze the eight user stories, infer the detailed requirements, define the solution design for each feature area (NIO/WebSocket, registry pairing, dynamic lookup, throttling, logging, MVEL upgrade, JDBC), and produce the development plan for the increment.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - NIO stack enablement via deploy.properties toggle",
      "activity_description": "Implement parsing of the NIO toggle in deploy.properties, wire transport selection at startup so the Grizzly-based NIO HTTP stack can replace the blocking transport, keep the blocking stack as default, and unit test both configurations.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - WebSocket components for flows",
      "activity_description": "Develop the WebSocket module: inbound and outbound endpoints usable in Mule flows, message receiver/dispatcher, connection/session handling, XML schema and namespace handler for configuration, plus unit and functional tests on the NIO stack.",
      "most_likely_effort": 72
    },
    {
      "activity_id": "A4",
      "activity_name": "U2 - Registry pairing via registry key",
      "activity_description": "Implement the registry pairing agent: registry key configuration, pairing handshake with the registry REST API, secure local persistence of pairing state, application lifecycle listeners that register/unregister HTTP endpoints of all deployed apps with the paired registry, and unit/integration tests.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "A5",
      "activity_name": "U3 - Dynamic lookup component (dynamic router)",
      "activity_description": "Implement the dynamic lookup message processor supporting runtime endpoint resolution via expressions and registry-based dynamic endpoint resolution, including lookup caching, timeout/fallback handling, XML configuration support, and unit tests.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A6",
      "activity_name": "U4 - Throttling policies for flow endpoints",
      "activity_description": "Implement throttling policy enforcement at flow endpoints integrated with registry-supplied policy definitions: token-bucket rate limiting, configurable limits and rejection responses, policy retrieval/refresh from the registry, and unit/integration tests.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A7",
      "activity_name": "U5 - Business event and transaction ID logging",
      "activity_description": "Add logging of custom business events and transaction IDs (via event tracking and log MDC) when developing an application, with appropriate configuration toggles and unit tests verifying log output.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A8",
      "activity_name": "U6 - MVEL 2.1.8 dependency upgrade",
      "activity_description": "Upgrade the MVEL dependency to 2.1.8 across all modules, resolve any API/behavior changes, run the MVEL and DataMapper regression test suites, and fix resulting issues.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "U7 - Out-of-the-box JDBC support for five databases",
      "activity_description": "Provide minimal-configuration JDBC connectivity for Oracle, PostgreSQL, Sybase, MS SQL Server and DB2: preconfigured data-source templates, dialect/connector settings, documentation of driver installation, and integration tests against a real instance of each database (MySQL already done).",
      "most_likely_effort": 88
    },
    {
      "activity_id": "A10",
      "activity_name": "U8 - SQL query DEBUG logging option",
      "activity_description": "Implement an optional DEBUG-mode logging facility in the JDBC transport (logging connection/statement wrapper) that outputs all executed queries to the Mule logs, including configuration option and tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A11",
      "activity_name": "Cross-story integration and system testing",
      "activity_description": "Perform end-to-end integration testing across all features of the increment (NIO/WebSocket, registry pairing, dynamic lookup, throttling, event logging, MVEL upgrade, JDBC databases and query logging), including defect fixing found during system test.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A12",
      "activity_name": "User documentation and release notes",
      "activity_description": "Write configuration references and user documentation for the new features (deploy.properties toggle, WebSocket components, registry key pairing, dynamic lookup, throttling policies, JDBC templates, query logging) plus release notes.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A13",
      "activity_name": "Packaging, release preparation and final hardening",
      "activity_description": "Prepare the release build and distribution packages, verify the full regression suite, perform final bug fixing and stabilization of the increment prior to delivery.",
      "most_likely_effort": 32
    }
  ],
  "reported_total": {
    "most_likely_effort": 564
  }
}

